function evensFirst(nums: number[]): number[] {
  let w = 0;
  for (let i = 0; i < nums.length; i++) {
    if (nums[i] % 2 === 0) {
      [nums[i], nums[w]] = [nums[w], nums[i]];
      w++;
    }
  }
  return nums;
}

